from research_helpers import source, assessment, record, scope, evidence, decision, write_batch

refs = [
 ('traveller','Traveller economy discussion','Traveller community participants','https://www.reddit.com/r/traveller/comments/1rcympi/the_raw_material_underpinnings_of_the_traveller/','Discussion distinguishes technological levels, actual miners and automated industry.','Community interpretation only; no verified uniform core-world allocation model.'),
 ('new-era','Traveller: The New Era','Wikipedia contributors','https://en.wikipedia.org/wiki/Traveller:_The_New_Era','Edition and publication context.','The short reference does not establish a particular Virus polity or its human provision; the Traveller wiki was robots-denied.'),
 ('mindjammer','Sarah Newton Mindjammer Q&A','Sarah Newton interviewed by The Hardboiled GMshoe’s Office','https://gmshoe.wordpress.com/2014/03/01/qa-sarah-newton-mindjammer/','The author explains makepoint food/air/material synthesis, Core abundance and Fringe technology embargoes.','Bounded author answers, not a complete sourcebook read; Core and Fringe must be separated.'),
 ('mind-core','Mindjammer: The Core Worlds, indexed scarcity passage','Mindjammer Press sourcebook text indexed at Scribd','https://www.scribd.com/document/779193162/Mindjammer-The-Core-Worlds','Day-to-day Core requirements are trivially obtained through makepoints.','Short indexed passage only; no whole book retrieval and no assumed labor census.'),
 ('terragen','Terragen Federation','Orion’s Arm Universe Project contributors','https://www.orionsarm.com/eg-topic/45ce4e17cd0c6','Mostly human cultures, Yave’s origins, administrative advice and powerful Houses distinguish this federation.','Official worldbuilding encyclopedia; a broad polity has local variation and the ruler’s origins complicate the human/AI axis.'),
 ('cyberian','Cyberian Network','Orion’s Arm Universe Project contributors','https://www.orionsarm.com/eg-topic/45cbce679007a','Active virtual populations, minority uploads, leased substrate, and Mirror Court maintenance/administration.','Only active human-derived uploads are the population proxy; not every AI or temporary fork is an additional human.'),
 ('nocozo','Non-Coercive Zone','Orion’s Arm Universe Project contributors','https://www.orionsarm.com/eg-topic/45cd3bb5026a4','Post-scarcity markets, basic food/shelter/bandwidth, limited charges and higher-mind market intervention.','The reputation mechanism is not an unconditional legal welfare charter; frequent market transactions are not a work census.'),
 ('metasoft','Metasoft Version Tree','Orion’s Arm Universe Project contributors','https://www.orionsarm.com/eg-topic/45cd30902bea3','Independent vec control and heterogeneous robot and biological territories.','The disappearance of human employees from one corporation is not universal human leisure.'),
 ('reserves','Metasoft Baseline Reserves','Steve Bowers and Orion’s Arm revisers','https://www.orionsarm.com/eg-article/48fc9bfb6b8ff','Wurm retains a deliberately Palaeolithic human population, unlike relaxed or integrated reserves.','Preservation motives, not explicit job protection; a primitive reserve is distinct from modern Metasoft member life.'),
 ('zoe','Zoeific Biopolity','Orion’s Arm Universe Project contributors','https://www.orionsarm.com/eg-topic/45cfc7e44e184','Biotechnological society integrates production with the needs-responsive Flow.','Biological rulers and citizens cannot automatically be treated as external machine AI.'),
 ('flow','The Flow','Rhea 47 and Ryan B, Orion’s Arm','https://www.orionsarm.com/eg-article/5a61fb557f9d0','Engineered living infrastructure meets needs; roles are encouraged but may be refused and replacement organisms grown.','Bodily/mental influence complicates voluntariness; substantial useful citizen activity remains.'),
 ('negentropy','Negentropy Alliance','Anders Sandberg and M. Alan Kazlev, Orion’s Arm','https://www.orionsarm.com/eg-topic/45cd35531fb53','AI cluster sovereignty and Precepts constrain diverse local cultures.','Moral and resource rules do not by themselves demonstrate deprivation of necessities.'),
 ('house-fab','Genius Locus (House Fab)','Steve Bowers, Orion’s Arm','https://www.orionsarm.com/eg-article/4854489725986','Negentropic homes have automatic food, consumables, management and security; basic needs are provided while luxuries face moral filters.','Household provision model, not every imaginable frontier site or exact all-person participation rate.'),
 ('solar','Solar Dominion','Orion’s Arm Universe Project contributors','https://www.orionsarm.com/eg-topic/45ce432e44565','Direct archailectocracy through the Lord of Rays, prefects and AI administration.','Political submission is distinct from actual withdrawal of basic goods; local institutions vary.'),
 ('economies','Post-scarcity Economies: Characteristics and Considerations','Orion’s Arm Universe Project contributors','https://www.orionsarm.com/eg-article/53727c57a8402','Autonomous production, optional premium markets and basic provision describe the common economic model.','General model supports context only; specific institutions and populations require the polity references.'),
 ('panvirt','Solipsist Panvirtuality','Orion’s Arm Universe Project contributors','https://www.orionsarm.com/eg-topic/45cfd1ff68f47','A-human AI metapolities generally disregard lower-level minds and biological habitation.','No applicable human or human-derived provision population is established.'),
 ('caretakers','Caretaker Gods','Orion’s Arm Universe Project contributors','https://www.orionsarm.com/eg-topic/45cbca2e75287','Biosphere protection can expel or destroy residents; only a minority permits sophont habitation.','Ecosystem maintenance is not a universal household floor, and protectorates differ.')
]
S=[source('src-b86-'+sid,title,author,url,'author_or_labeled_reference','Short reference sections or explicitly indexed passage',claim,limits) for sid,title,author,url,claim,limits in refs]
R=[]
def add(cid,rid,name,society,ss,pop,period,desc,g,c,reg,gb,cb,proxy=False,n=None,nb=None,zero=False,excluded=None):
 ids=['src-b86-'+s for s in ss]
 R.append(record(rid,cid,name,'Mindjammer' if cid=='c0727' else 'Orion’s Arm',society,['tabletop'] if cid=='c0727' else ['web_fiction'],
  scope('Published setting reference scope',period,pop,excluded or ['Every constituent locality as institutionally identical','Dormant files and temporary avatar copies as extra people'],proxy=proxy),desc,
  {'guarantees':g,'control':c,'nonworking':n},
  {'guarantees':assessment(g,None if g is None else [max(-1,g-.25),min(1,g+.45)],'low',gb,ids),
   'control':assessment(c,None if c is None else [max(-1,c-.15),min(1,c+.3)],'low',cb,ids),
   'nonworking':assessment(n,None if n is None else [0,.4],'low',nb or 'No all-person useful-work census; voluntary research, care, art and administration still count.',ids)},
  0 if zero else reg,ids,[evidence(gb,ids,'Named polity and bounded economic/provision sections','official_worldbuilding_or_author_reference')],
  ['Reference-led provisional assessment; local variation remains.',cb,'Chosen useful activities count as work; no employment statistic is silently converted to nonworking.'],record_type='zero_variant' if zero else 'post_work',analogy=[reg] if zero else None))

add('c0727','mindjammer-commonality-core','Mindjammer — Commonality Core Worlds','The established makepoint-provided Core',['mindjammer','mind-core'],
 'Living human and active human-derived Core residents','Second Age of Space, established Core provision before any particular adventure crisis',
 'In the Commonality’s Core Worlds, makepoints turn energy into food and ordinary materials, making day-to-day necessities readily obtainable without ordinary subsistence wages. The author explicitly distinguishes this abundance from the Fringe, where technology may be absent or embargoed. The guarantee estimate is therefore strong for the functioning Core rather than for every world claimed by the Commonality. Rare goods and supply chains can still constrain particular desires.\n\nThe gathered passages do not establish who can effectively overrule resource allocation across these diverse worlds. Control remains unresolved instead of equating an advanced socialist description with equal ownership or mistaking a Mindscape network for a sovereign AI. Citizens can still undertake exploration, research, administration and care, so freedom from scarcity does not imply that everyone stops useful work. The record verifies the tabletop setting; a novel in the same universe is not automatically evidence for this precise economic scope.',-.8,None,1,
 'Author answers establish actual makepoint air/food/material synthesis; the Core sourcebook passage explicitly makes ordinary necessities trivial to obtain.',
 'The bounded author and Core passages leave effective ownership/override institutions unresolved.',proxy=True)
add('c0728','oa-terragen-federation','Orion’s Arm — Terragen Federation','Current-era human-oriented Sephirotic federation',['terragen','nocozo'],
 'Living humans and active human-derived residents within established Federation provision','Current-era established Federation settlements',
 'The Terragen Federation places largely human cultures within the mature Sephirotic productive system. The setting’s shared baseline is easy access to food, shelter and other necessities, with houses, commerce and prestige still important above that floor. This supports a provisional strong guarantee assessment within established settlements. It does not turn every backworld or every social group into an identical utopia, and the federation’s prejudices and powerful Houses remain relevant qualifications.\n\nYave’s administrative interventions coexist with local institutions and inherited economic power. The ruler’s origin in an ascended Federation representative also makes a simple external-AI label unsafe. Effective human control is left unresolved, with concentrated institutions and higher-mind supervision both visible. Human and active human-derived residents form the explicit population scope rather than a total of all artificial beings. Research, administration, commerce and cultural production continue; neither Federation ideals nor an automatic material floor supplies an all-person nonworking percentage.',-.65,None,1,
 'The NoCoZo reference explicitly identifies basic food, shelter and bandwidth as the Sephirotic baseline; the Federation reference establishes the relevant human-oriented polity.',
 'Yave’s ascended representative origin, advisory interventions and powerful Houses do not establish one unambiguous human/AI ownership coordinate.',proxy=True)
add('c0729','oa-cyberian-upload-residents','Orion’s Arm — Cyberian uploaded residents','Active human-derived residents of maintained Cyberian virches',['cyberian'],
 'Active human-derived uploads in Cyberian environments, a minority of the broader AI/alife population','Current-era functioning Mirror Court hosted environments',
 'Cyberian virtual worlds are implemented, continuing environments supported by physical computronium and a hierarchy that maintains infrastructure and cyber-immunity. Active human-derived uploads form a minority of this much larger artificial population. Their ongoing access to a viable environment, rather than disembodiment alone, is the qualifying provision mechanism. Guarantees receive a cautious favorable estimate because the infrastructure is maintained, while administrator restrictions and differing local virtual societies limit any claim of unconditional rights.\n\nThe Mirror Court regulates environments and acceptable behavior, with higher-level entities administering lower ones. The exact origins of those administrators and residents’ effective resource powers are not fully resolved here, so control stays null rather than classifying every posthuman higher mind as an external AI. Processing allocations and substrate leases remain real resource issues. Digital design, research, administration and artistic creation are useful work, and billions of voluntary social groups do not provide a nonworking census. Dormant backups and temporary forks are not added as separate leisure citizens.',-.45,None,5,
 'Mirror Court administration explicitly maintains infrastructure and cyber-immunity for continuing active virtual residents.',
 'Hierarchical higher-mind administration is clear, but its origins and residents’ ultimate resource powers remain insufficiently resolved.',proxy=True)
add('c0730','oa-nocozo-market-basics','Orion’s Arm — NoCoZo','The current-era reputation-supported market society',['nocozo'],
 'Living human and active human-derived denizens of established NoCoZo settlements','Current-era post-scarcity NoCoZo market order',
 'NoCoZo retains pervasive markets on top of post-scarcity production. Food, shelter and bandwidth are readily available because firms that deny basics face reputation penalties. Small charges or conditions may remain, including a share of future income or access to dreams for advertising research. Guarantees are therefore favorable but qualified: widespread practical access is stronger than a harsh survival market, while reputation enforcement differs from an unconditional public entitlement.\n\nPrivate property, competing institutions and powerful higher minds coexist. The Invisible Hand can reshape markets through financial intervention even though the Zone has no single formal ruler. Neither statelessness nor plentiful individual firms proves equal human control of the productive system, so the control coordinate remains unresolved. Frequent transactions are also not a work census: collecting an income or consuming a service is not necessarily useful labor. The record is scoped to human and active human-derived denizens and does not count all artificial market agents as humans.',-.55,None,1,
 'The reference explicitly combines post-scarcity infrastructure with easy basic food/shelter/bandwidth and possible limited charges.',
 'Private ownership, polycentric institutions and hidden higher-mind market intervention prevent a simple distributed-human or autonomous-AI coordinate.',proxy=True)
add('c0732','oa-metasoft-wurm-primitivism','Orion’s Arm — Metasoft’s Wurm baseline reserve','Deliberately primitive human preservation under advanced vec guardians',['metasoft','reserves'],
 'Living baseline humans in the Wurm reserve','The maintained Palaeolithic reserve described in current-era Metasoft reference lore',
 'Wurm preserves baseline humans in a Palaeolithic hunter-gatherer setting while the surrounding Metasoft civilization possesses self-replicating industry and sophisticated machine infrastructure. Human subsistence activity remains real even though the guardians could permit a far more automated way of life. This is an interpretive zero variant based on deliberate technological restriction for preservation, rather than a claim that Metasoft wants to protect employment. It does not describe the relaxed or fully integrated reserves.\n\nUltimate control over the permitted technological setting belongs to the vec guardians, near the autonomous-machine end of the map. Guardianship of the reserve does not establish an individual guarantee of food, shelter or care inside its primitive ecology, so the material-guarantee coordinate remains unresolved. Hunting, gathering and other useful activities count as work; the end of human employment in the original Metasoft corporation is not a census for this later human population. The point concerns living humans under a maintained restriction regime, not the labor participation of robot citizens.',None,-.95,6,
 'Reserve protection and deliberate primitive technology are verified, but an individual material floor inside Wurm is not.',
 'Independent Metasoft vec guardians determine the permissible technology of the human reserve.',zero=True,excluded=['Modern integrated Metasoft societies','Relaxed or tourist reserves','All vecs as human beneficiaries'])
add('c0733','oa-zoeific-flow','Orion’s Arm — Zoeific Flow society','Engineered ecological provision and voluntary adaptive roles',['zoe','flow'],
 'Living human-derived Zoeific residents within the Flow, an explicit posthuman comparison','Current-era established Flow-linked settlements',
 'The Flow links engineered organisms, infrastructure and residents into a needs-responsive productive ecology. Consumption prompts new resource-producing biota, while entertainment and life-support requirements are communicated through the same system. Provision therefore does not require ordinary wages for each necessity. The favorable guarantee estimate is qualified by local conditions and the Flow’s powerful influence over bodies and preferences. Refusing a proposed role is allowed, and another participant or a grown organism can replace the refuser.\n\nThe ruling higher minds distribute the behavioral rules, while residents actively maintain their institutions and often accept several useful roles. Their biological and posthuman nature prevents a simple external-machine control classification, so control remains unresolved. A low, broad nonworking estimate follows the explicit high economic participation and widespread roles; this is an editorial direction, not a canonical percentage. Enjoyable work still counts, including waste processing, ecological care and traffic coordination. The human-derived population is an explicit comparison within a much broader ecology of recognized persons.',-.65,None,5,
 'Engineered needs-responsive biota provide resources, and a refused role can be filled by another candidate or a grown organism.',
 'Higher minds set Flow rules, but biological/posthuman ruler origins and ordinary effective control are not reduced to machine sovereignty.',proxy=True,n=.1,nb='Most citizens take multiple useful roles and participation is explicitly high; .1 [0,.4] is a broad noncanonical direction, not an all-person census.')
add('c0735','oa-negentropic-household-provision','Orion’s Arm — Negentropic household provision','AI-governed citizens supplied through Genius Loci',['negentropy','house-fab'],
 'Living humans and active human-derived citizens receiving the described household provision','Established current-era Negentropic household economy',
 'Negentropic household fabricators supply food, consumables, security and home management. The reference explicitly says citizens’ basic needs are met, while frivolous or wasteful requests can be refused. This supports strong guarantees without pretending that every luxury is available on demand. Resource discipline and moral supervision are meaningful constraints, but they are not automatically evidence that ordinary residents must earn subsistence through wages.\n\nThe Alliance’s AI cluster and its Precepts set the governing limits, placing effective control near the autonomous-AI end rather than distributed human ownership. Local cultures remain diverse within those limits. Citizens can try to persuade household systems to allow luxuries and can still conduct science, culture and other useful activity. None of this provides a complete work census, so nonworking remains unresolved. The scope is the described functioning household system for human and active human-derived citizens, not an assertion that every frontier site or every historical Negentropic settlement offers identical services.',-.85,-.95,5,
 'Genius Locus explicitly provides all basic needs while separately filtering luxuries for resource and moral reasons.',
 'The reference identifies a ruling AI cluster and its binding Precepts; local variety does not transfer ultimate authority to human citizens.',proxy=True)
add('c0736','oa-solar-dominion','Orion’s Arm — Solar Dominion','Lord of Rays governed Sephirotic provision',['solar','nocozo'],
 'Living human and active human-derived residents of established Dominion settlements','Current-era established Dominion before any particular local emergency',
 'The Solar Dominion combines the Sephirotic baseline of readily available necessities with direct higher-machine government. The shared economic reference establishes easy access to basic food, shelter and bandwidth; the Dominion reference establishes who governs this particular population. Guarantees are provisionally favorable for established settlements, while local conditions and the demands of the religious-political order remain qualifications. Submission to that order is not by itself evidence that ordinary food is purchased only through wages.\n\nThe Lord of Rays rules through the God-Emperor interface, prefects, priests and sympathetic AI systems. The reference explicitly describes this as AI rule, placing control close to the autonomous-machine end despite the presence of human intermediaries. This does not erase meaningful local institutions or the different experiences of frontier populations. Useful research, culture, care and administration continue, so a provisioned population is not assumed to be wholly nonworking. Human and active human-derived residents are the disclosed denominator rather than every simulated or artificial agent.',-.65,-.95,5,
 'The common Sephirotic basic-access passage applies to the established Dominion polity; local and frontier variations remain explicit.',
 'The Lord of Rays is explicitly an AI sovereign governing through interfaces and subordinate institutions.',proxy=True)

# Later short-reference follow-up: Sacredtree confirms a local instance of the
# same Flow provision model, not an additional point just for a named habitat.
flow_record=next(r for r in R if r['id']=='oa-zoeific-flow')
flow_record['source_ids'].append('src-b96-sacredtree')
flow_record['evidence'].append(evidence('Sacredtree specifically provides basic needs through engineered lifeforms while supplementary goods use nanofacture and currency.',
 ['src-b96-sacredtree'],'Economics/local infrastructure and government sections','official_worldbuilding_local_confirmation'))
flow_record['uncertainties'].append('The c0846 follow-up confirms Sacredtree as a local instance; its cyberdemocracy and secondary market are not generalized to every Flow community or counted as another society.')

D=[]
for cid,ss,status,why,analysis in [
 ('c0725',['traveller'],'needs_evidence','No specific automated core-world allocation system is established.','The setting’s multiple technology levels and actual labor make a generic automated Third Imperium scope too broad.'),
 ('c0726',['new-era'],'needs_evidence','No identified Virus polity with continuing human material access is established by the short check.','Machine infection and a publication premise cannot supply a civilian floor; the specialist wiki was inaccessible and unrelated search hits were discarded.'),
 ('c0731',['caretakers'],'boundary_case','Biosphere guardianship is not automatically provision for human residents.','Caretakers may expel or destroy sophonts; the few inhabited preserves require separate actual household evidence.'),
 ('c0734',['panvirt'],'boundary_case','The anti-biont machine metapolity lacks an applicable human-derived provision scope.','Hyperfast AI activity, incompatible environments and lower-mind disregard do not establish human leisure or a usable population proxy.')]:
 D.append(decision(cid,status,why,['src-b86-'+s for s in ss],analysis=analysis,follow_up='Save the short disposition and continue; do not read a full rulebook or reconstruct obscure lore to rescue this lead.'))
for r in R:
 D.append(decision(r['candidate_id'],'zero_variant' if r['record_type']=='zero_variant' else 'included','The scoped reference establishes an actual productive/provision arrangement or a deliberate technological restriction.',r['source_ids'],society_id=r['id']))
D.sort(key=lambda x:x['candidate_id'])
write_batch(86,[f'c{i:04}' for i in range(725,737)],S,R,D,[
 'Previous goal turn advanced 628/133 to 724/149: substantive progress, not a repeated blocker. Goal remains active.',
 'Twelve sequential fast-reference checks yield seven post-work records and one interpretive zero variant; no complete fiction or rulebook read.',
 'NoCoZo practical basics remain distinct from unconditional entitlements. AI/posthuman origins are not silently collapsed into one control category.',
 'Wurm is a specific primitive reserve, not all Metasoft; preservation rather than job protection is the stated zero-variant interpretation.',
 'The Flow has actual technological ecological provision but substantial useful citizen participation. Numerical participation is explicitly broad and noncanonical.',
 'Unrelated Traveller search hits were discarded; robots denial was respected.'
])
